'use strict';
// Original SVG scenery and sprites keep this prototype sharp at every screen size.
function combatBackdrop(){return `<svg class="arena-backdrop" viewBox="0 0 1200 500" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
 <defs><linearGradient id="arenaSky" x2="0" y2="1"><stop stop-color="#667da7"/><stop offset=".62" stop-color="#e8b297"/><stop offset="1" stop-color="#f4cf93"/></linearGradient><linearGradient id="arenaGround" x2="0" y2="1"><stop stop-color="#bca278"/><stop offset="1" stop-color="#645362"/></linearGradient><radialGradient id="arenaSun"><stop stop-color="#fff2c4" stop-opacity=".65"/><stop offset="1" stop-color="#fff2c4" stop-opacity="0"/></radialGradient><g id="arenaPine"><path d="M-7 0h14v220H-7z" fill="#514154"/><path d="M0-105l-61 112h30l-56 78h35l-58 76H108L51 85h34L31 7h30z" fill="#48465b"/><path d="M0-105l-35 112h17l-37 78h24l-40 76H0z" fill="#5c6071"/></g><g id="arenaOak"><path d="M-12 0h24v200H-12zM-2 50l-55-55-6 8 50 75zm10 35L64 25l-7-9L0 62z" fill="#514150"/><path d="M-91-7l15-46 44-9 22-35 53 12 25 34 44 13 8 47-42 24-37-7-29 22-51-13-18-25z" fill="#a16b65"/><path d="M-91-7l15-46 44-9 22-35 53 12 25 34-39-2-32 21-52-6-11 23z" fill="#cb906e"/><path d="M-62-51l24-10 30-29 33 10-34 18-11 20z" fill="#e7b27c"/></g></defs>
 <path fill="url(#arenaSky)" d="M0 0h1200v500H0z"/><circle cx="865" cy="100" r="210" fill="url(#arenaSun)"/><circle cx="865" cy="100" r="40" fill="#ffe3ad"/>
 <path d="M0 240L115 112l132 121L408 70l162 163L710 128l135 100L1021 75l179 161v264H0z" fill="#7d819a"/><path d="M305 178l103-108 82 102-83-30zM940 150l81-75 78 81-78-28z" fill="#c7bbbd"/>
 <path d="M0 265l169-83 184 95 219-64 165 51 185-88 278 102v222H0z" fill="#72768a"/>
 ${[20,120,210,320,410,520,650,760,900,1010,1120,1220].map((x,i)=>`<use href="#arenaPine" transform="translate(${x} ${260+i%3*17}) scale(${.55+i%3*.14})" opacity=".6"/>`).join('')}
 <path d="M0 350q230-70 450-23t750-19v192H0z" fill="url(#arenaGround)"/><path d="M-30 380Q360 321 615 363t620-18v86Q850 390 601 401T-30 435z" fill="#d5b18a"/><path d="M0 408q300-65 575-14t625-19" fill="none" stroke="#f9f6f4" stroke-width="3" opacity=".45"/>
 <path d="M840 90L560 365h220L900 105z" fill="#ffdf9c" opacity=".1"/>
 <use href="#arenaOak" transform="translate(76 209) scale(1.8)"/><use href="#arenaOak" transform="translate(1140 225) scale(1.65)"/><use href="#arenaPine" transform="translate(-28 140) scale(1.6)"/><use href="#arenaPine" transform="translate(1250 164) scale(1.6)"/>
 <g fill="#696173"><path d="M140 371l22-17h39l23 27-45 10-43-7zM956 363l20-24h35l21 26-30 12z"/><path d="M1048 422l33-27h51l27 32-69 15z" fill="#514b5b"/></g>
 <g fill="#4c424f"><path d="M0 461l36-34 15 34 22-52 13 58 45-31-4 45 62-12 37 31H0zM1200 445l-29-22-8 35-29-48-11 52-35-23 9 38-83-9-25 32h211z"/></g><g fill="#a16b65" opacity=".6">${Array.from({length:24},(_,i)=>`<rect x="${(i*173+57)%1200}" y="${360+i%5*21}" width="${3+i%4*3}" height="2"/>`).join('')}</g>
 </svg>`}
function combatHeroSprite(){return `<svg viewBox="0 0 80 100" role="img" aria-label="Your adventurer holding a sword" shape-rendering="crispEdges"><path d="M23 41h28v40H12V61h6V48z" fill="#9d4f59"/><path d="M23 47h18v35H12V64h6V52z" fill="#c36d66"/><path d="M29 72h12v21H26v-9h3zm20 0h11v16h6v6H48z" fill="#383749"/><path d="M25 89h18v7H23v-4zm23 0h20v7H48z" fill="#69505a"/><path d="M28 43h28v30H25V50z" fill="#51718a"/><path d="M31 44h7v26h-7z" fill="#80969d"/><path d="M27 66h31v7H27z" fill="#c49b65"/><path d="M41 65h7v9h-7z" fill="#f0cb84"/><path d="M30 17h23v25H30zM51 25h7v10h-7z" fill="#dfae88"/><path d="M26 18v-8h24v5h7v9H35v9h-8v-7h-4v-8z" fill="#55404e"/><path d="M30 12h17v5H30z" fill="#80605b"/><path d="M46 25h4v4h-4z" fill="#35364a"/><path d="M53 48h7v12h10v7H54z" fill="#e1b38b"/><path d="M64 59h16v5H64z" fill="#dfb35f"/><path d="M69 58V34l5-9 4 9v24z" fill="#d7e2e5"/><path d="M69 36h4v21h-4z" fill="#93b5ca"/><path d="M18 51l14-5 13 6v19L32 84 18 72z" fill="#3b4259"/><path d="M21 54l11-4 10 4v15L32 79 21 70z" fill="#be9264"/><path d="M29 52h5v23h-5z" fill="#efd39a"/></svg>`}
function combatEnemySprite(type){if(type==='bear')return `<svg viewBox="0 0 120 100" role="img" aria-label="Forest bear" shape-rendering="crispEdges"><path d="M12 47h8V30h17v-8h52v7h16v15h7v36H98v15H82V78H52v17H35V78H16z" fill="#59434b"/><path d="M27 32h55v9h17v28H43v-9H23V45h4z" fill="#8f6355"/><path d="M44 28h33v8H44zM54 38h37v14H54z" fill="#ac7c61"/><path d="M13 29h18v17H13zm26-6h15v16H39z" fill="#64464c"/><path d="M17 33h9v7h-9zm26-6h7v7h-7z" fill="#bd8d73"/><path d="M8 43h41v27H14v-8H5V49h3z" fill="#956957"/><path d="M4 57h21v15H4z" fill="#c39a78"/><path d="M2 54h12v9H2zM21 47h5v5h-5z" fill="#302f3d"/><path d="M17 49h4v2h-4z" fill="#f5ce8c"/><path d="M35 90h17v5H35zm47 0h16v5H82z" fill="#302f3d"/></svg>`;
 return enemyPortrait(type)}
function combatScene(c){if(c.onMap)return '';if(c.guided)return guidedCombatScene(c);const revealed=c.phase==='reveal',p=c.player,e=c.enemy,r=c.result;const effect=(side)=>{if(!revealed)return '';const result=r[side];return `<span class="arena-damage">${result.damage?'-'+result.damage:result.dodged?'DODGE':'BLOCK'}</span>${result.blocked?`<span class="arena-block">${result.blocked} blocked</span>`:''}${result.dodged?'<span class="arena-dodge-label">DODGED</span>':''}${result.healed?`<span class="arena-heal">+${result.healed} HP</span>`:''}`};
 const playerAttacks=revealed&&r.playerCards.some(n=>!n.startsWith('Defense')&&!n.startsWith('Second Wind')&&!n.startsWith('Mending'));
 const enemyAttacks=revealed&&r.enemyCards.some(n=>!n.startsWith('Defense')&&!n.startsWith('Dodge'));
 return `<section class="combat-arena arena-type-${c.place.enemyType||'guardian'} ${revealed?'round-resolved':''} ${preferences.reduceMotion?'arena-reduced-motion':''}" style="--player-travel:${enemyAttacks?'16vw':'30vw'};--enemy-travel:${playerAttacks?'-16vw':'-30vw'}" aria-label="2D combat clearing">
 ${combatBackdrop()}<div class="arena-vignette"></div><div class="arena-location"><span>THE WOODLAND CLEARING</span><small>${c.practice?'PRACTICE':'WILDERNESS'} / ROUND ${c.round}</small></div>
 <div class="arena-hud arena-hud-player"><strong>${escapeText(p.name)}</strong><div class="arena-health"><i style="width:${p.hp/p.maxHP*100}%;--hp-before:${(c.beforeHP?.player??p.hp)/p.maxHP*100}%"></i></div><span>${p.hp} / ${p.maxHP} HP <small>· ${p.mana} mana · ✦ ${p.dice}</small></span></div>
 <div class="arena-hud arena-hud-enemy"><strong>${escapeText(e.name)}</strong><div class="arena-health"><i style="width:${e.hp/e.maxHP*100}%;--hp-before:${(c.beforeHP?.enemy??e.hp)/e.maxHP*100}%"></i></div><span>${e.hp} / ${e.maxHP} HP <small>· ${revealed?'Revealed':'Hand hidden'}</small></span></div>
 <div class="arena-actor arena-player ${playerAttacks?'actor-attacking':''} ${revealed&&r.player.blocked?'actor-guarding':''}"><div class="actor-shadow"></div><div class="actor-sprite">${combatHeroSprite()}</div>${effect('player')}${revealed&&r.player.blocked?'<div class="guard-ring"></div>':''}${revealed&&r.player.healed?'<div class="arena-healing-aura"></div>':''}</div>
 <div class="arena-actor arena-enemy ${enemyAttacks?'actor-attacking':''} ${revealed&&r.enemy.dodged?'actor-dodging':''} ${e.hp===0?'actor-fallen':''}"><div class="actor-shadow"></div><div class="actor-sprite">${combatEnemySprite(c.place.enemyType||'guardian')}</div>${effect('enemy')}${revealed&&r.enemy.blocked?'<div class="guard-ring"></div>':''}</div>
 ${enemyAttacks?'<div class="impact-particles impact-on-player"><i></i><i></i><i></i><i></i><i></i></div>':''}${playerAttacks?'<div class="impact-particles impact-on-enemy"><i></i><i></i><i></i><i></i><i></i></div>':''}
 ${playerAttacks?'<div class="arena-slash slash-enemy"></div>':''}${enemyAttacks?'<div class="arena-slash slash-player"></div>':''}
 ${revealed&&r.playerCards.some(n=>/Bolt|Spark|Seal/.test(n))?'<div class="arena-projectile"></div>':''}
 <div class="arena-bottom-caption">${revealed?(r.outcome==='victory'?'Opponent defeated':r.outcome==='defeat'?'You have fallen':r.outcome==='draw'?'Both fighters fall':'Both hands resolved'):'Choose your cards. Your opponent has already committed.'}</div>
 <div class="arena-motes"><i></i><i></i><i></i><i></i></div></section>`}
